mapper.select:
SELECT c.*, u.nickname AS creator_name, cat.name AS category_name
FROM t_character c
LEFT JOIN t_user u ON c.creator_id = u.id
LEFT JOIN t_category cat ON c.category_id = cat.id

    INNER JOIN t_character_tag ct ON c.id = ct.character_id AND ct.tag_id = #{tagId}


    AND c.status = #{status}
    AND c.category_id = #{categoryId}
    AND c.creator_id = #{creatorId}

        AND (c.name LIKE CONCAT('%', #{keyword}, '%') OR c.description LIKE CONCAT('%', #{keyword}, '%'))


ORDER BY c.hot_score DESC, c.id DESC
